import{_ as a,o,c as i,a2 as s}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Carga de modelos","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/03-carga-de-modelos.md","filePath":"ia/vllm/03-carga-de-modelos.md","lastUpdated":1789040978000,"isDraft":false}'),l={name:"ia/vllm/03-carga-de-modelos.md"};function n(r,e,d,t,c,p){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="carga-de-modelos" tabindex="-1">Carga de modelos <a class="header-anchor" href="#carga-de-modelos" aria-label="Permalink to &quot;Carga de modelos&quot;">​</a></h1><p>vLLM carga <strong>pesos + tokenizer + config</strong> de un id del Hub o de una ruta local. Eso ocurre al construir <code>LLM(...)</code> o al arrancar <code>vllm serve &lt;modelo&gt;</code>. Si falla la carga, no hay API que depurar: primero VRAM, id, revisión y permiso del repo.</p><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">CLI serve</a> (<code>--model</code>, <code>--tokenizer</code>, <code>--revision</code>, <code>--quantization</code>, <code>--max-model-len</code>, <code>--trust-remote-code</code>), <a href="https://docs.vllm.ai/en/latest/examples/basic/offline_inference/" target="_blank" rel="noreferrer">offline inference</a>.</p><h2 id="donde-esta-el-modelo" tabindex="-1">Dónde está el modelo <a class="header-anchor" href="#donde-esta-el-modelo" aria-label="Permalink to &quot;Dónde está el modelo&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-0.6B</span></span></code></pre></div><p>Equivalente offline:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vllm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LLM</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLM(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Qwen/Qwen3-0.6B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li><strong>Id del Hub</strong> (<code>org/nombre</code>): descarga (o reusa) el cache de Hugging Face.</li><li><strong>Ruta local:</strong> directorio con <code>config.json</code>, tokenizer y shards. Útil cuando no hay red o ya copiaste los pesos.</li></ul><p><code>--tokenizer</code> solo si el tokenizer no va en el mismo repo. <code>--revision</code> fija un commit o tag del Hub cuando necesitas reproducir un snapshot.</p><p>Repos <strong>gated</strong> o privados: token en el entorno (<code>HF_TOKEN</code>) o <code>hf auth login</code>. Sin eso, el error parece de descarga.</p><h2 id="lo-que-cabe-en-gpu" tabindex="-1">Lo que cabe en GPU <a class="header-anchor" href="#lo-que-cabe-en-gpu" aria-label="Permalink to &quot;Lo que cabe en GPU&quot;">​</a></h2><p>Tras los pesos, vLLM reserva KV cache. Si no entra:</p><ul><li>modelo más pequeño, o cuantizado;</li><li><code>--max-model-len</code> menor que el contexto máximo del card;</li><li><code>--gpu-memory-utilization</code> más bajo si compartes la GPU (capítulo 5);</li><li><code>--tensor-parallel-size</code> si el modelo es más grande que una GPU (capítulo 5).</li></ul><p><code>--max-model-len</code> recorta prompt + salida. No lo subas “por si acaso”: comes VRAM y no ganas calidad.</p><h2 id="cuantizacion" tabindex="-1">Cuantización <a class="header-anchor" href="#cuantizacion" aria-label="Permalink to &quot;Cuantización&quot;">​</a></h2><p><code>--quantization</code> (y el argumento homónimo de <code>LLM</code>) indica el método cuando aplica (<code>awq</code>, <code>gptq</code>, <code>fp8</code>, … según lo que soporte tu versión). Muchos checkpoints ya traen <code>quantization_config</code> en el card: entonces no inventes un método distinto al del repo.</p><p>GGUF y otros formatos tienen recetas propias en la doc de offline inference; no mezcles un GGUF con flags de AWQ.</p><h2 id="codigo-remoto" tabindex="-1">Código remoto <a class="header-anchor" href="#codigo-remoto" aria-label="Permalink to &quot;Código remoto&quot;">​</a></h2><p><code>--trust-remote-code</code> ejecuta código Python del repo del modelo. Actívalo <strong>solo</strong> si el card lo exige y confías en el origen. El default es no confiar.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Id mal escrito o modelo de otra arquitectura no soportada.</li><li>Tokenizer de otro checkpoint.</li><li><code>trust_remote_code=True</code> por costumbre.</li><li>Ignorar que el default de <code>--model</code> en la CLI es un Qwen pequeño: en producción el id lo pones tú.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Fija modelo + revisión en la config del servicio.</li><li>Monta <code>~/.cache/huggingface</code> (o el cache de vLLM) en volumen para no redescargar.</li><li>Comprueba <code>GET /v1/models</code> después de cargar: el nombre que ves es el que debe ir en el JSON.</li><li>Si el card pide una versión mínima de <code>transformers</code> / vLLM, alinea el entorno.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Carga el mismo id por Hub y, si puedes, desde una copia local.</li><li>Arranca con <code>--max-model-len</code> pequeño y uno grande; mira si el segundo OOM.</li><li>Lee el card de un modelo AWQ y decide si debes pasar <code>--quantization</code> o no.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./04-batching-y-rendimiento">Batching y rendimiento</a>.</p>`,27)])])}const m=a(l,[["render",n]]);export{h as __pageData,m as default};
